def tabbed_page(html):
    controls='''<div class="reader-bar"><span class="reader-caption">مطالعه به سبک خودت</span><div class="reader-controls"><div class="size-control" role="group" aria-label="اندازهٔ نوشته"><button type="button" id="text-smaller" aria-label="کوچک‌تر کردن نوشته">کوچک‌تر −</button><output id="text-size-value" aria-live="polite" aria-label="اندازهٔ نوشته">۱۰۰٪</output><button type="button" id="text-larger" aria-label="بزرگ‌تر کردن نوشته">بزرگ‌تر +</button></div><button type="button" id="theme-toggle" class="theme-switch" role="switch" aria-checked="false" aria-label="حالت تیره"><span>حالت تیره</span><span class="switch-track" aria-hidden="true"></span></button></div></div>'''
    tabs=[('lessons','درس‌ها'),('questions','پرسش‌ها'),('flashcards','فلش‌کارت‌ها'),('review','مرور سریع'),('corrections','اصلاحات و ابهام‌ها'),('source','منبع')]
    tab_nav='<div class="study-tabs" id="study-tabs" role="tablist" aria-label="بخش‌های مطالعه">'+''.join(f'<button type="button" role="tab" id="tab-{key}" aria-controls="panel-{key}" aria-selected="{str(key=="lessons").lower()}" tabindex="{0 if key=="lessons" else -1}">{label}</button>' for key,label in tabs)+'</div>'
    start=html.index('<details class="mobile-contents">')
    end=html.index('<section class="reference-section" id="quick-review">')
    lesson_panel=html[start:end]+'</main></div>'
    original_intro=re.search(r'<section class="intro".*?</section>',lesson_panel,re.S).group(0)
    instructions=re.search(r'<p class="method">.*?(?=<div class="toolbar">)',original_intro,re.S).group(0)
    instructions=instructions.replace('صفحه را ببند و پاسخ‌ها را روی کاغذ بنویس.','به زبانهٔ «پرسش‌ها» برو و پاسخ‌ها را روی کاغذ بنویس.')
    progress=re.search(r'<div class="progress-box">.*?</p></div>',original_intro,re.S).group(0)
    new_intro='<section class="intro lesson-intro"><h2 id="how">مطالعهٔ درس‌ها</h2><p class="section-lead">هر بار یک درس را باز کن و بخوان. علامت مرور هر درس را پس از مطالعه ثبت کن.</p><div class="toolbar"><button id="expand-lessons" type="button">باز کردن همهٔ درس‌ها</button><button id="collapse-lessons" type="button">جمع کردن درس‌ها</button></div>'+progress+'</section>'
    lesson_panel=lesson_panel.replace(original_intro,new_intro)
    sections={key:re.search(r'<section class="reference-section" id="'+key+r'">.*?</section>',html,re.S).group(0) for key in ['quick-review','written-practice','source-questions','uncertainties','coverage']}
    sections['coverage']='<section class="reference-section"><h2>راهنمای استفاده</h2><details class="study-instructions"><summary>روش مطالعه و ارجاع به جزوه</summary>'+instructions+'</details><div class="toolbar"><button id="print-guide" type="button" class="primary">چاپ راهنما</button><label class="print-choice"><input id="print-answers" type="checkbox">پاسخ‌ها هم چاپ شوند</label></div></section>'+sections['coverage']
    recall=[];cards=[];options=['<option value="">كل الدروس</option>']
    for i,l in enumerate(lessons,1):
        options.append(f'<option value="{i}">درس {i}: {escape(l["title"])}</option>')
        recall.append(f'<details class="recall-group"><summary>درس {i} · {l["title"]}<span>{len(l["questions"])} پرسش</span></summary><div class="recall-content">{refs(l["pages"])}'+''.join(l['questions'])+'</div></details>')
        for question in l['questions']:
            prompt=re.search(r'<p class="q-prompt">(.*?)</p>',question,re.S).group(1)
            answer=re.search(r'<div class="answer-body">(.*?)</div></details>',question,re.S).group(1)
            cards.append(f'<article class="flashcard" data-flash-lesson="{i}"><span class="flash-label">درس {i} · {l["title"]}</span><h3>{prompt}</h3><details class="flash-answer"><summary>دیدن پاسخ کارت</summary><div class="answer-body">{answer}</div></details></article>')
    recall_bank='<section class="reference-section recall-bank" id="lesson-questions"><h2>پرسش‌های درس‌ها</h2><p class="section-lead">۴۳ پرسش، مرتب‌شده بر اساس درس. درس موردنظر را باز کن، ابتدا پاسخ را بنویس؛ سپس پاسخ پیشنهادی و نکات ضروری را ببین.</p>'+''.join(recall)+'</section>'
    flashcards='<section class="reference-section" id="flashcards"><h2>فلش‌کارت‌های یادآوری</h2><p class="section-lead">۴۳ کارت برگرفته از تمرین‌های درس‌ها؛ برای مرور ساخته شده‌اند و پیش‌بینی سؤال امتحان نیستند. پیش از دیدن پاسخ، توضیح را از حافظه بگو یا بنویس.</p><div class="flash-toolbar"><label for="flash-lesson">انتخاب درس<select id="flash-lesson">'+''.join(options)+'</select></label><span class="flash-position" id="flash-position" aria-live="polite">۱ از ۴۳</span></div><div class="flash-deck">'+''.join(cards)+'</div><div class="flash-navigation"><button id="flash-previous" type="button">کارت قبلی</button><button id="flash-next" type="button" class="primary">کارت بعدی</button></div></section>'
    contents={'lessons':lesson_panel,'questions':'<div class="panel-content">'+recall_bank+sections['written-practice']+sections['source-questions']+'</div>','flashcards':'<div class="panel-content">'+flashcards+'</div>','review':'<div class="panel-content">'+sections['quick-review']+'</div>','corrections':'<div class="panel-content">'+sections['uncertainties']+'</div>','source':'<div class="panel-content">'+sections['coverage']+'</div>'}
    panels=''.join(f'<section class="tab-panel" role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}" tabindex="0">{contents[key]}</section>' for key,label in tabs)
    footer=html[html.index('<footer class="footnote">'):html.index('</footer>')+len('</footer>')]
    return add_home_navigation(html[:start]+'<div class="reader-dock">'+controls+tab_nav+'</div>'+panels+footer+'</div><script>'+JS+'</script></body></html>')

def build():
    font_data=base64.b64encode((ROOT/'_work'/'vazirmatn.woff2').read_bytes()).decode('ascii')
